// Parse pattern recognition request
const request = $input.first().json;

// Required fields validation
if (!request.operation_type) {
  return [{
    json: {
      error: 'Missing required field: operation_type',
      valid_operations: ['identify_patterns', 'match_pattern', 'learn_success', 'analyze_trends', 'recommend_patterns'],
      status: 'invalid_request'
    }
  }];
}

// Build request context
const context = {
  operation_type: request.operation_type,
  character_id: request.character_id || 'unknown',
  session_id: request.session_id || 'unknown',
  timestamp: new Date().toISOString(),
  input_data: request.input_data || {},
  analysis_context: {
    search_scope: request.search_scope || 'all_characters',
    time_period: request.time_period || 'last_30_days',
    success_threshold: request.success_threshold || 0.7,
    pattern_complexity: request.pattern_complexity || 'all',
    character_class_filter: request.character_class_filter || null,
    automation_type_filter: request.automation_type_filter || null
  },
  options: {
    include_explanations: request.include_explanations !== false,
    include_code_examples: request.include_code_examples !== false,
    include_performance_metrics: request.include_performance_metrics !== false,
    learning_mode: request.learning_mode || 'adaptive',
    confidence_threshold: request.confidence_threshold || 0.6
  }
};

return [{
  json: context
}];

// Handle pattern identification operation
const request = $input.first().json;

if (!request.input_data.scenario_description) {
  return [{
    json: {
      error: 'Missing required field: input_data.scenario_description',
      status: 'invalid_data'
    }
  }];
}

// Extract scenario features
const scenarioFeatures = {
  description: request.input_data.scenario_description,
  character_class: request.input_data.character_class || 'unknown',
  character_level: request.input_data.character_level || 1,
  party_composition: request.input_data.party_composition || [],
  environment: request.input_data.environment || 'unknown',
  available_resources: request.input_data.available_resources || {},
  constraints: request.input_data.constraints || [],
  objectives: request.input_data.objectives || [],
  urgency_level: request.input_data.urgency_level || 'normal'
};

// Predefined pattern templates
const patternTemplates = {
  protection: {
    scenarios: ['party_taking_damage', 'low_health_member', 'incoming_threat', 'defensive_position'],
    triggers: ['health_below_threshold', 'threat_detected', 'party_in_danger', 'character_under_attack'],
    actions: ['cast_protection_spell', 'use_defensive_ability', 'intercept_attack', 'heal_party_member'],
    success_factors: ['timing', 'resource_management', 'threat_assessment', 'positioning']
  },
  combat: {
    scenarios: ['multiple_enemies', 'single_powerful_enemy', 'boss_encounter', 'ambush_situation'],
    triggers: ['combat_started', 'enemy_detected', 'health_below_threshold', 'opportunity_arises'],
    actions: ['attack_primary_target', 'use_special_ability', 'buff_allies', 'debuff_enemies'],
    success_factors: ['target_prioritization', 'resource_efficiency', 'timing', 'positioning']
  },
  healing: {
    scenarios: ['party_member_injured', 'multiple_injuries', 'status_conditions', 'prevention_needed'],
    triggers: ['health_below_threshold', 'condition_detected', 'combat_ended', 'danger_detected'],
    actions: ['cast_healing_spell', 'remove_condition', 'apply_buff', 'preventive_healing'],
    success_factors: ['prioritization', 'efficiency', 'timing', 'resource_management']
  },
  utility: {
    scenarios: ['obstacle_encountered', 'puzzle_situation', 'information_needed', 'preparation_required'],
    triggers: ['obstacle_detected', 'puzzle_presented', 'information_gaps', 'downtime_available'],
    actions: ['use_utility_skill', 'cast_utility_spell', 'analyze_situation', 'prepare_resources'],
    success_factors: ['creativity', 'efficiency', 'timing', 'resource_utilization']
  }
};

// Identify likely pattern type
const likelyPatternType = identifyPatternType(scenarioFeatures, patternTemplates);

function identifyPatternType(scenario, templates) {
  const description = scenario.description.toLowerCase();
  const scores = {};

  for (const [type, template] of Object.entries(templates)) {
    let score = 0;

    // Score based on scenario keywords
    template.scenarios.forEach(scenario_keyword => {
      if (description.includes(scenario_keyword.replace('_', ' '))) {
        score += 2;
      }
    });

    // Score based on objectives
    scenario.objectives.forEach(objective => {
      if (type === 'protection' && (objective.includes('protect') || objective.includes('defend'))) score += 2;
      if (type === 'combat' && (objective.includes('attack') || objective.includes('damage'))) score += 2;
      if (type === 'healing' && (objective.includes('heal') || objective.includes('restore'))) score += 2;
      if (type === 'utility' && (objective.includes('help') || objective.includes('solve'))) score += 2;
    });

    // Score based on class
    if (scenario.character_class) {
      if (type === 'protection' && ['fighter', 'paladin', 'cleric'].includes(scenario.character_class.toLowerCase())) score += 1;
      if (type === 'combat' && ['fighter', 'paladin', 'ranger', 'rogue'].includes(scenario.character_class.toLowerCase())) score += 1;
      if (type === 'healing' && ['cleric', 'druid', 'paladin'].includes(scenario.character_class.toLowerCase())) score += 1;
      if (type === 'utility' && ['wizard', 'rogue', 'bard'].includes(scenario.character_class.toLowerCase())) score += 1;
    }

    scores[type] = score;
  }

  // Return the pattern type with highest score
  return Object.keys(scores).reduce((a, b) => scores[a] > scores[b] ? a : b);
}

return [{
  json: {
    ...request,
    operation: 'identify_patterns',
    scenario_features: scenarioFeatures,
    likely_pattern_type: likelyPatternType,
    pattern_templates: patternTemplates,
    search_strategy: 'semantic_similarity_and_template_matching'
  }
}];

// Handle pattern matching operation
const request = $input.first().json;

if (!request.input_data.current_situation) {
  return [{
    json: {
      error: 'Missing required field: input_data.current_situation',
      status: 'invalid_data'
    }
  }];
}

// Extract situation features
const situationFeatures = {
  current_situation: request.input_data.current_situation,
  character_state: request.input_data.character_state || {},
  environment_state: request.input_data.environment_state || {},
  party_state: request.input_data.party_state || {},
  available_resources: request.input_data.available_resources || {},
  recent_events: request.input_data.recent_events || [],
  immediate_needs: request.input_data.immediate_needs || []
};

// Pattern matching criteria
const matchingCriteria = {
  similarity_threshold: request.options.confidence_threshold || 0.6,
  max_results: request.input_data.max_results || 5,
  include_failed_patterns: request.input_data.include_failed_patterns || false,
  weighting_factors: {
    situation_similarity: 0.4,
    character_similarity: 0.3,
    outcome_success: 0.2,
    recent_success: 0.1
  }
};

return [{
  json: {
    ...request,
    operation: 'match_pattern',
    situation_features: situationFeatures,
    matching_criteria: matchingCriteria,
    search_strategy: 'multi_factor_similarity_matching'
  }
}];

// Handle success learning operation
const request = $input.first().json;

if (!request.input_data.execution_result) {
  return [{
    json: {
      error: 'Missing required field: input_data.execution_result',
      status: 'invalid_data'
    }
  }];
}

// Extract execution result features
const executionFeatures = {
  pattern_id: request.input_data.pattern_id || generatePatternId(request.input_data),
  execution_result: request.input_data.execution_result,
  success_metrics: {
    primary_goal_achieved: request.input_data.execution_result.success || false,
    effectiveness_score: request.input_data.execution_result.effectiveness_score || 0,
    execution_time: request.input_data.execution_result.execution_time || 0,
    resource_efficiency: request.input_data.execution_result.resource_efficiency || 0,
    user_satisfaction: request.input_data.execution_result.user_satisfaction || 0
  },
  context_factors: {
    character_level: request.input_data.character_level || 1,
    party_size: request.input_data.party_size || 1,
    difficulty_level: request.input_data.difficulty_level || 'normal',
    environmental_factors: request.input_data.environmental_factors || []
  },
  learning_data: {
    unexpected_outcomes: request.input_data.execution_result.unexpected_outcomes || [],
    user_feedback: request.input_data.execution_result.user_feedback || '',
    improvement_suggestions: request.input_data.execution_result.improvement_suggestions || []
  }
};

function generatePatternId(inputData) {
  const crypto = require('crypto');
  const hash = crypto.createHash('md5');
  const patternString = JSON.stringify({
    situation: inputData.current_situation,
    actions: inputData.actions_taken,
    character_class: inputData.character_class
  });
  return hash.update(patternString).digest('hex').substring(0, 8);
}

// Calculate learning value
const learningValue = {
  overall_score: calculateOverallScore(executionFeatures.success_metrics),
  pattern_strength: calculatePatternStrength(executionFeatures),
  transferability: calculateTransferability(executionFeatures),
  improvement_potential: calculateImprovementPotential(executionFeatures)
};

function calculateOverallScore(metrics) {
  return (
    (metrics.primary_goal_achieved ? 0.4 : 0) +
    (metrics.effectiveness_score * 0.3) +
    (metrics.resource_efficiency * 0.2) +
    (metrics.user_satisfaction * 0.1)
  );
}

function calculatePatternStrength(features) {
  const base_score = learningValue.overall_score;

  // Adjust for context factors
  if (features.context_factors.difficulty_level === 'hard') base_score += 0.1;
  if (features.context_factors.party_size > 3) base_score += 0.1;
  if (features.learning_data.user_feedback.includes('excellent')) base_score += 0.2;

  return Math.min(base_score, 1.0);
}

function calculateTransferability(features) {
  let transferability = 0.5; // Base transferability

  // Higher transferability for general patterns
  if (features.context_factors.party_size <= 4) transferability += 0.2;
  if (features.context_factors.difficulty_level !== 'legendary') transferability += 0.2;
  if (features.learning_data.unexpected_outcomes.length === 0) transferability += 0.1;

  return Math.min(transferability, 1.0);
}

function calculateImprovementPotential(features) {
  let potential = 0;

  if (features.success_metrics.effectiveness_score < 0.8) potential += 0.3;
  if (features.success_metrics.resource_efficiency < 0.7) potential += 0.3;
  if (features.learning_data.improvement_suggestions.length > 0) potential += 0.2;
  if (features.learning_data.user_feedback.includes('improve')) potential += 0.2;

  return Math.min(potential, 1.0);
}

return [{
  json: {
    ...request,
    operation: 'learn_success',
    execution_features: executionFeatures,
    learning_value: learningValue,
    learning_strategy: 'reinforcement_and_adaptation'
  }
}];

// Retrieve existing pattern data from knowledge base
const request = $input.first().json;

// Simulate knowledge base retrieval
const existingPatterns = {
  protection_patterns: [
    {
      pattern_id: 'prot_001',
      name: 'Tank Shield Response',
      description: 'Automatically protect party member when health drops below 30%',
      success_rate: 0.85,
      usage_count: 45,
      character_classes: ['fighter', 'paladin'],
      complexity: 'medium',
      triggers: ['ally_health_low'],
      actions: ['use_protection_ability'],
      performance_metrics: {
        avg_response_time: 1.2,
        avg_effectiveness: 0.88,
        resource_efficiency: 0.75
      }
    },
    {
      pattern_id: 'prot_002',
      name: 'Proactive Healing Buff',
      description: 'Pre-cast protection spells before dangerous encounters',
      success_rate: 0.92,
      usage_count: 28,
      character_classes: ['cleric', 'paladin'],
      complexity: 'high',
      triggers: ['danger_detected', 'combat_imminent'],
      actions: ['cast_protection_spell', 'apply_party_buff'],
      performance_metrics: {
        avg_response_time: 2.5,
        avg_effectiveness: 0.91,
        resource_efficiency: 0.82
      }
    }
  ],
  combat_patterns: [
    {
      pattern_id: 'comb_001',
      name: 'Focus Fire Coordination',
      description: 'Coordinate party attacks on single high-priority target',
      success_rate: 0.78,
      usage_count: 67,
      character_classes: ['fighter', 'ranger', 'rogue'],
      complexity: 'medium',
      triggers: ['high_priority_target', 'multiple_enemies'],
      actions: ['coordinate_attack', 'use_high_damage_ability'],
      performance_metrics: {
        avg_response_time: 0.8,
        avg_effectiveness: 0.82,
        resource_efficiency: 0.79
      }
    }
  ],
  healing_patterns: [
    {
      pattern_id: 'heal_001',
      name: 'Triage Healing System',
      description: 'Prioritize healing based on injury severity and role importance',
      success_rate: 0.89,
      usage_count: 93,
      character_classes: ['cleric', 'druid'],
      complexity: 'high',
      triggers: ['party_injury', 'combat_healing_needed'],
      actions: ['assess_injuries', 'prioritize_healing', 'cast_optimal_spell'],
      performance_metrics: {
        avg_response_time: 1.5,
        avg_effectiveness: 0.91,
        resource_efficiency: 0.84
      }
    }
  ]
};

return [{
  json: {
    ...request,
    existing_patterns: existingPatterns,
    knowledge_base_status: 'available',
    pattern_count: Object.values(existingPatterns).flat().length
  }
}];

// Create AI pattern analysis prompt
const request = $input.first().json;

const analysisPrompt = `
You are an expert Pattern Recognition AI that analyzes automation patterns for D&D characters. Your task is to analyze the pattern operation and provide intelligent insights.

## Operation: ${request.operation}
## Character ID: ${request.character_id}
## Session ID: ${request.session_id}

${request.scenario_features ? `
## Scenario Features:
- Description: ${request.scenario_features.description}
- Character Class: ${request.scenario_features.character_class}
- Character Level: ${request.scenario_features.character_level}
- Objectives: ${request.scenario_features.objectives.join(', ')}
- Likely Pattern Type: ${request.likely_pattern_type}
` : ''}

${request.situation_features ? `
## Situation Features:
- Current Situation: ${request.situation_features.current_situation}
- Immediate Needs: ${request.situation_features.immediate_needs.join(', ')}
- Available Resources: ${JSON.stringify(request.situation_features.available_resources)}
` : ''}

${request.execution_features ? `
## Execution Features:
- Pattern ID: ${request.execution_features.pattern_id}
- Success: ${request.execution_features.success_metrics.primary_goal_achieved}
- Effectiveness Score: ${request.execution_features.success_metrics.effectiveness_score}
- User Feedback: ${request.execution_features.learning_data.user_feedback}
` : ''}

## Existing Patterns in Knowledge Base:
${request.existing_patterns ? Object.entries(request.existing_patterns).map(([type, patterns]) => 
  `\n### ${type.toUpperCase()}:\n${patterns.map(p => 
    `- ${p.name}: ${p.description} (Success Rate: ${p.success_rate * 100}%)`).join('\n')}`).join('\n') : 'No existing patterns available'}

## Analysis Required:
Based on the operation type, provide detailed analysis:

${request.operation === 'identify_patterns' ? `
For pattern identification, analyze:
1. Best matching patterns from the knowledge base
2. Pattern applicability to current scenario
3. Success probability for each pattern
4. Required adaptations and modifications
5. Implementation recommendations
` : ''}

${request.operation === 'match_pattern' ? `
For pattern matching, analyze:
1. Most similar patterns to current situation
2. Similarity scores and matching criteria
3. Contextual differences and adaptations needed
4. Risk assessment for each match
5. Recommended pattern selection strategy
` : ''}

${request.operation === 'learn_success' ? `
For success learning, analyze:
1. Pattern performance and success factors
2. Learning insights and improvements needed
3. Pattern generalization opportunities
4. Knowledge base updates required
5. Future application recommendations
` : ''}

## Response Format (JSON):
{
  "analysis_summary": "Brief overview of pattern analysis results",
  "identified_patterns": [
    {
      "pattern_id": "pattern identifier",
      "pattern_name": "descriptive pattern name",
      "match_score": 0.95,
      "applicability": "high/medium/low",
      "success_probability": 0.88,
      "required_adaptations": ["modifications needed"],
      "implementation_complexity": "simple/medium/complex",
      "resource_requirements": ["resources needed"],
      "risk_factors": ["potential risks"],
      "recommendations": ["specific recommendations"]
    }
  ],
  "pattern_insights": {
    "common_success_factors": ["elements that lead to success"],
    "failure_patterns": ["patterns that often fail"],
    "optimization_opportunities": ["ways to improve patterns"],
    "contextual_dependencies": ["factors that affect pattern performance"]
  },
  "learning_recommendations": {
    "new_patterns_to_create": ["suggestions for new patterns"],
    "existing_patterns_to_update": ["patterns that need modification"],
    "knowledge_gaps": ["areas where more patterns are needed"],
    "research_suggestions": ["areas for further investigation"]
  },
  "next_steps": ["recommended follow-up actions"]
}

Focus on actionable insights that improve pattern recognition and matching accuracy while ensuring character success.`;

return [{
  json: {
    ...request,
    deepseek_prompt: analysisPrompt,
    analysis_type: 'pattern_recognition'
  }
}];

// Process AI pattern analysis results
const aiResponse = $input.first().json;
const originalRequest = items.find(item => item.json.deepseek_prompt)?.json;

if (!aiResponse.choices || !aiResponse.choices[0]?.message?.content) {
  return [{
    json: {
      error: 'Invalid AI response from pattern analysis',
      status: 'ai_error'
    }
  }];
}

try {
  const analysisResult = JSON.parse(aiResponse.choices[0].message.content);

  // Enhance analysis with additional metadata
  const enhancedAnalysis = {
    analysis_id: generateAnalysisId(),
    operation_type: originalRequest.operation,
    character_id: originalRequest.character_id,
    session_id: originalRequest.session_id,
    timestamp: new Date().toISOString(),
    pattern_analysis_result: analysisResult,
    pattern_recommendations: generatePatternRecommendations(analysisResult, originalRequest),
    learning_insights: extractLearningInsights(analysisResult),
    knowledge_base_updates: determineKnowledgeBaseUpdates(analysisResult),
    confidence_scores: calculateConfidenceScores(analysisResult),
    implementation_readiness: assessImplementationReadiness(analysisResult),
    metadata: {
      ai_provider: 'deepseek',
      model: 'deepseek-chat',
      tokens_used: aiResponse.usage?.total_tokens || 0,
      patterns_analyzed: originalRequest.existing_patterns?.pattern_count || 0,
      analysis_depth: originalRequest.options?.include_explanations ? 'detailed' : 'standard'
    }
  };

  function generateAnalysisId() {
    return 'pr_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }

  function generatePatternRecommendations(analysis, request) {
    const recommendations = [];

    if (analysis.identified_patterns && analysis.identified_patterns.length > 0) {
      const topPattern = analysis.identified_patterns[0];
      recommendations.push({
        type: 'implement_pattern',
        pattern_id: topPattern.pattern_id,
        pattern_name: topPattern.pattern_name,
        confidence: topPattern.match_score,
        complexity: topPattern.implementation_complexity,
        estimated_success: topPattern.success_probability,
        priority: topPattern.applicability === 'high' ? 'immediate' : 'normal'
      });
    }

    if (analysis.learning_recommendations?.new_patterns_to_create) {
      analysis.learning_recommendations.new_patterns_to_create.forEach(pattern => {
        recommendations.push({
          type: 'create_pattern',
          description: pattern,
          priority: 'research'
        });
      });
    }

    return recommendations;
  }

  function extractLearningInsights(analysis) {
    return {
      success_factors: analysis.pattern_insights?.common_success_factors || [],
      failure_patterns: analysis.pattern_insights?.failure_patterns || [],
      optimization_opportunities: analysis.pattern_insights?.optimization_opportunities || [],
      contextual_factors: analysis.pattern_insights?.contextual_dependencies || []
    };
  }

  function determineKnowledgeBaseUpdates(analysis) {
    return {
      new_patterns_needed: analysis.learning_recommendations?.new_patterns_to_create || [],
      patterns_to_update: analysis.learning_recommendations?.existing_patterns_to_update || [],
      knowledge_gaps: analysis.learning_recommendations?.knowledge_gaps || [],
      research_priorities: analysis.learning_recommendations?.research_suggestions || []
    };
  }

  function calculateConfidenceScores(analysis) {
    const scores = {};

    if (analysis.identified_patterns && analysis.identified_patterns.length > 0) {
      const avgMatchScore = analysis.identified_patterns.reduce((sum, p) => sum + p.match_score, 0) / analysis.identified_patterns.length;
      scores.overall_confidence = avgMatchScore;
      scores.pattern_match_confidence = avgMatchScore;
      scores.analysis_confidence = 0.85; // AI confidence
    } else {
      scores.overall_confidence = 0.3;
      scores.pattern_match_confidence = 0.1;
      scores.analysis_confidence = 0.85;
    }

    return scores;
  }

  function assessImplementationReadiness(analysis) {
    const readiness = {
      can_implement_immediately: false,
      requires_adaptation: false,
      requires_research: false,
      overall_readiness: 'low'
    };

    if (analysis.identified_patterns && analysis.identified_patterns.length > 0) {
      const topPattern = analysis.identified_patterns[0];
      if (topPattern.applicability === 'high' && topPattern.implementation_complexity === 'simple') {
        readiness.can_implement_immediately = true;
        readiness.overall_readiness = 'high';
      } else if (topPattern.required_adaptations && topPattern.required_adaptations.length > 0) {
        readiness.requires_adaptation = true;
        readiness.overall_readiness = 'medium';
      }
    } else {
      readiness.requires_research = true;
      readiness.overall_readiness = 'low';
    }

    return readiness;
  }

  return [{
    json: enhancedAnalysis
  }];

} catch (error) {
  return [{
    json: {
      error: 'Failed to process pattern analysis',
      details: error.message,
      raw_response: aiResponse.choices[0].message.content,
      status: 'processing_error'
    }
  }];
}

// Update pattern knowledge base
const analysis = $input.first().json;

if (analysis.knowledge_base_updates.new_patterns_needed.length > 0 || 
    analysis.knowledge_base_updates.patterns_to_update.length > 0) {

  const knowledgeUpdate = {
    update_id: generateUpdateId(),
    analysis_id: analysis.analysis_id,
    character_id: analysis.character_id,
    session_id: analysis.session_id,
    timestamp: new Date().toISOString(),
    update_type: 'pattern_knowledge_update',
    updates: {
      new_patterns: analysis.knowledge_base_updates.new_patterns_needed.map(pattern => ({
        pattern_description: pattern,
        source_character_id: analysis.character_id,
        source_session_id: analysis.session_id,
        confidence: analysis.confidence_scores.overall_confidence,
        status: 'pending_creation'
      })),
      updated_patterns: analysis.knowledge_base_updates.patterns_to_update.map(pattern => ({
        pattern_name: pattern,
        update_reason: 'performance_optimization',
        suggested_improvements: analysis.learning_insights.optimization_opportunities,
        status: 'pending_update'
      }))
    },
    learning_data: {
      success_factors_learned: analysis.learning_insights.success_factors,
      failure_patterns_identified: analysis.learning_insights.failure_patterns,
      optimization_opportunities: analysis.learning_insights.optimization_opportunities
    }
  };

  function generateUpdateId() {
    return 'kbu_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);
  }

  return [{
    json: {
      ...analysis,
      knowledge_update: knowledgeUpdate
    }
  }];
}

return [{
  json: {
    ...analysis,
    knowledge_update: {
      message: 'No knowledge base updates required',
      update_id: null
    }
  }
}];

// Prepare final pattern recognition response
const analysis = $input.first().json;

const response = {
  status: 'success',
  timestamp: new Date().toISOString(),
  analysis_id: analysis.analysis_id,
  operation_type: analysis.operation_type,
  character_id: analysis.character_id,
  session_id: analysis.session_id,
  pattern_analysis: {
    summary: analysis.pattern_analysis_result.analysis_summary,
    patterns_identified: analysis.pattern_analysis_result.identified_patterns?.length || 0,
    top_recommendation: analysis.pattern_analysis_result.identified_patterns?.[0] || null,
    confidence_scores: analysis.confidence_scores
  },
  implementation_readiness: {
    ready_to_implement: analysis.implementation_readiness.can_implement_immediately,
    requires_adaptation: analysis.implementation_readiness.requires_adaptation,
    requires_research: analysis.implementation_readiness.requires_research,
    overall_readiness: analysis.implementation_readiness.overall_readiness
  },
  pattern_recommendations: analysis.pattern_recommendations,
  learning_insights: analysis.learning_insights,
  knowledge_base_updates: {
    new_patterns_needed: analysis.knowledge_base_updates.new_patterns_needed.length,
    patterns_to_update: analysis.knowledge_base_updates.patterns_to_update.length,
    knowledge_gaps_identified: analysis.knowledge_base_updates.knowledge_gaps.length
  },
  next_steps: analysis.pattern_analysis_result.next_steps,
  metadata: {
    tokens_used: analysis.metadata.tokens_used,
    patterns_analyzed: analysis.metadata.patterns_analyzed,
    analysis_depth: analysis.metadata.analysis_depth,
    ai_provider: analysis.metadata.ai_provider
  }
};

return [{
  json: response
}];

// Error handling
const error = $input.first().json;

const errorResponse = {
  status: 'error',
  timestamp: new Date().toISOString(),
  error: error.error || 'Pattern recognition failed',
  details: error.details || 'No additional details available',
  operation_type: error.operation_type || 'unknown',
  character_id: error.character_id || 'unknown',
  session_id: error.session_id || 'unknown',
  suggestions: [
    'Check the input data format and completeness',
    'Ensure operation type is valid',
    'Verify that scenario or situation information is provided',
    'Try with a more specific description'
  ]
};

return [{
  json: errorResponse
}];
